import runtime/effect.{type Effect}

pub type Model {
  Model(title: String)
}

pub type Msg {
  UserChangedTitle(String)
  TitleSaved
  TitleSaveFailed
}

pub fn update(model: Model, msg: Msg) -> #(Model, List(Effect(Msg))) {
  case msg {
    UserChangedTitle(title) -> #(
      Model(..model, title: title),
      [save_title(title)],
    )
    TitleSaved -> #(model, [])
    TitleSaveFailed -> #(model, [log("Could not save the title.")])
  }
}

@external(javascript, "./effects.mjs", "saveTitle")
fn save_title(title: String) -> Effect(Msg)

@external(javascript, "./effects.mjs", "log")
fn log(message: String) -> Effect(Msg)

